//! A raw UART driving an RS-485 transceiver: the line generated by the
//! host, break and all.
//!
//! Each packet is a zero octet at the [`BreakPlan`]'s lower rate — the
//! break and mark — then the start code and slots at 250 kbaud, 8N2.
//! Changing the rate waits for what was written to go out, so the octets
//! never overlap. The mark comes out longer than the plan's, by however
//! long the driver takes to change rate; E1.11 allows that.
//!
//! The line is refreshed continuously: receivers on it expect a packet
//! every frame time, not on change.
//!
//! # Not yet
//!
//! Receiving: detecting a break from user space needs the driver to mark
//! framing errors, which differs by platform. [`Transport::receive`] says
//! so, every time.
//!
//! # Concurrency
//!
//! `Send` and `Sync`; sends are serialised under a lock.

use crate::Error;
use crate::line::{BAUD, BreakPlan};
use crate::port::{Framing, Port};
use crate::widget::{UNIVERSE, WRITE};
use regalium_dmx_core::frame::Frame;
use regalium_dmx_core::transport::{Received, Transport};
use std::sync::{Mutex, PoisonError};
use std::time::Duration;

const LINE: Framing = Framing {
    baud: BAUD,
    two_stop: true,
};

/// An open UART.
#[derive(Debug)]
pub struct Uart {
    port: Port,
    plan: BreakPlan,
    out: Mutex<Vec<u8>>,
}

impl Uart {
    /// Opens `path` at 250 kbaud, 8N2, breaking by [`BreakPlan::STANDARD`].
    ///
    /// # Errors
    ///
    /// When it cannot be opened, or its driver refuses 250 kbaud.
    pub fn open(path: &str) -> Result<Self, Error> {
        Ok(Self {
            port: Port::open(path, LINE)?,
            plan: BreakPlan::STANDARD,
            out: Mutex::new(Vec::with_capacity(513)),
        })
    }
}

impl Transport for Uart {
    type Error = Error;

    fn protocol(&self) -> &'static str {
        "serial"
    }

    fn send(&self, universe: u32, frame: &Frame<'_>) -> Result<(), Error> {
        if universe != UNIVERSE {
            return Err(Error::Universe(universe));
        }
        let mut out = self.out.lock().unwrap_or_else(PoisonError::into_inner);
        out.clear();
        frame.encode(&mut out);
        self.port.frame(Framing {
            baud: self.plan.baud,
            two_stop: false,
        })?;
        self.port.write_all(&[0], WRITE)?;
        self.port.frame(LINE)?;
        self.port.write_all(&out, WRITE)?;
        Ok(())
    }

    fn receive(&self, _: &mut [u8], _: Duration) -> Result<Option<Received>, Error> {
        Err(Error::Unsupported("receiving DMX on a raw UART"))
    }
}
